import threading

class RWLock:
    def __init__(self):
        self.readers = 0
        self._mutex = threading.Lock()
        self._write_lock = threading.Lock()

    def acquire_read(self):
        with self._mutex:
            self.readers += 1
            if self.readers == 1:
                self._write_lock.acquire()

    def release_read(self):
        with self._mutex:
            self.readers -= 1
            if self.readers == 0:
                self._write_lock.release()

    def acquire_write(self):
        self._write_lock.acquire()

    def release_write(self):
        self._write_lock.release()

